import 'dart:io';
import 'dart:math' as math;

import 'package:flutter_test/flutter_test.dart';
import 'package:pmtiles/pmtiles.dart';

// The bundled test-address archive (generated by the infra build, spec §3).
// Opened the way loadCampusTiles opens an archive: PmTilesArchive.fromBytes.
// Read from disk, not rootBundle, so it is a plain unit test.
const String _archivePath = 'assets/tambor.pmtiles';

// The street point of the author's address.
const double _streetLat = -7.2567;
const double _streetLng = -35.8900;

/// Slippy-map tile column of [lng] at [zoom].
int _tileX(double lng, int zoom) => ((lng + 180) / 360 * (1 << zoom)).floor();

/// Slippy-map tile row of [lat] at [zoom].
int _tileY(double lat, int zoom) {
  final rad = lat * math.pi / 180;
  final n = 1 << zoom;
  return ((1 - math.log(math.tan(rad) + 1 / math.cos(rad)) / math.pi) / 2 * n)
      .floor();
}

void main() {
  late PmTilesArchive archive;

  setUpAll(() async {
    archive = await PmTilesArchive.fromBytes(
      await File(_archivePath).readAsBytes(),
    );
  });

  test('tambor_archive_covers_zoom_12_to_15', () {
    expect(archive.minZoom, 12);
    expect(archive.maxZoom, 15);
  });

  test('tambor_archive_bounds_contain_the_street_point', () {
    expect(archive.minPosition.latitude, lessThanOrEqualTo(_streetLat));
    expect(archive.maxPosition.latitude, greaterThanOrEqualTo(_streetLat));
    expect(archive.minPosition.longitude, lessThanOrEqualTo(_streetLng));
    expect(archive.maxPosition.longitude, greaterThanOrEqualTo(_streetLng));
  });

  test('tambor_archive_serves_a_non_empty_tile_at_the_street_point', () async {
    final tile = await archive.tile(
      ZXY(15, _tileX(_streetLng, 15), _tileY(_streetLat, 15)).toTileId(),
    );
    expect(tile.bytes(), isNotEmpty);
  });
}
